#undef stonerview_win_release

void stonerview_win_release(stonerview_state *st) {
  for (osc_t *osc = st->oscroot; osc;) {
    osc_t *next = osc->next;
    free(osc);
    osc = next;
  }
  st->oscroot = NULL;
  stonerview_win_release_upstream(st);
}
